ALTER TABLE public.businesses ADD COLUMN IF NOT EXISTS guardian_profile jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.businesses ADD COLUMN IF NOT EXISTS guardian_ai_block jsonb;
CREATE OR REPLACE FUNCTION public.guardian_snapshot(_biz uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE checks jsonb;
BEGIN
 IF NOT public.has_biz_role(_biz,ARRAY['owner','manager','accountant']::member_role[]) THEN RAISE EXCEPTION 'Owner, manager or accountant access required'; END IF;
 SELECT jsonb_agg(jsonb_build_object('code',code,'issues',n)) INTO checks FROM (
 SELECT 'unbalanced_journals' code,count(*) n FROM (SELECT e.id FROM journal_entries e LEFT JOIN journal_lines l ON l.entry_id=e.id AND l.business_id=_biz WHERE e.business_id=_biz GROUP BY e.id HAVING coalesce(sum(l.debit-l.credit),0)<>0 OR count(l.id)=0)x
 UNION ALL SELECT 'sale_totals',count(*) FROM sales s WHERE s.business_id=_biz AND (s.total<>s.subtotal-s.discount+s.tax OR s.total<>s.paid+s.due OR s.subtotal<>coalesce((SELECT sum(line_total) FROM sale_items WHERE sale_id=s.id AND business_id=_biz),0) OR s.cogs<>coalesce((SELECT sum(qty*unit_cost) FROM sale_items WHERE sale_id=s.id AND business_id=_biz),0))
 UNION ALL SELECT 'purchase_totals',count(*) FROM purchases p WHERE p.business_id=_biz AND (p.total<>p.subtotal-p.discount+p.tax+p.transport_cost+p.loading_cost+p.courier_cost+p.insurance_cost+p.other_cost OR p.total<>p.paid+p.due OR p.subtotal<>coalesce((SELECT sum(line_total) FROM purchase_items WHERE purchase_id=p.id AND business_id=_biz),0))
 UNION ALL SELECT 'stock_movements',count(*) FROM (SELECT coalesce(s.branch_id,m.branch_id) FROM (SELECT * FROM stock WHERE business_id=_biz)s FULL JOIN (SELECT branch_id,variant_id,sum(qty_change) qty FROM stock_movements WHERE business_id=_biz GROUP BY branch_id,variant_id)m USING(branch_id,variant_id) WHERE coalesce(s.qty,0)<>coalesce(m.qty,0))x
 UNION ALL SELECT 'stock_imei',count(*) FROM (SELECT coalesce(s.branch_id,i.branch_id) FROM (SELECT st.* FROM stock st JOIN product_variants v ON v.id=st.variant_id JOIN products p ON p.id=v.product_id JOIN categories c ON c.id=p.category_id WHERE st.business_id=_biz AND c.is_serialized)s FULL JOIN (SELECT branch_id,variant_id,count(*) qty FROM product_imeis WHERE business_id=_biz AND status IN ('IN_STOCK','RESERVED') GROUP BY branch_id,variant_id)i USING(branch_id,variant_id) WHERE coalesce(s.qty,0)<>coalesce(i.qty,0))x
 UNION ALL SELECT 'sold_imei_links',count(*) FROM product_imeis i WHERE i.business_id=_biz AND i.status='SOLD' AND NOT EXISTS(SELECT 1 FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE si.id=i.sale_item_id AND si.imei_id=i.id AND si.business_id=_biz AND s.business_id=_biz AND s.status='posted')
 UNION ALL SELECT 'negative_stock',count(*) FROM stock WHERE business_id=_biz AND qty<0
 UNION ALL SELECT 'negative_money',count(*) FROM money_account_balances WHERE business_id=_biz AND balance<0
 UNION ALL SELECT 'customer_control',CASE WHEN coalesce((SELECT sum(current_due) FROM customer_balances WHERE business_id=_biz),0)<>coalesce((SELECT sum(l.debit-l.credit) FROM journal_lines l JOIN accounts a ON a.id=l.account_id WHERE l.business_id=_biz AND a.code='1100'),0) THEN 1 ELSE 0 END
 UNION ALL SELECT 'supplier_control',CASE WHEN coalesce((SELECT sum(current_payable) FROM supplier_balances WHERE business_id=_biz),0)<>coalesce((SELECT sum(l.credit-l.debit) FROM journal_lines l JOIN accounts a ON a.id=l.account_id WHERE l.business_id=_biz AND a.code='2010'),0) THEN 1 ELSE 0 END
 UNION ALL SELECT 'inventory_control',CASE WHEN coalesce((SELECT sum(qty*avg_cost) FROM stock WHERE business_id=_biz),0)<>coalesce((SELECT sum(l.debit-l.credit) FROM journal_lines l JOIN accounts a ON a.id=l.account_id WHERE l.business_id=_biz AND a.code='1200'),0) THEN 1 ELSE 0 END
 UNION ALL SELECT 'money_control',count(*) FROM money_accounts m WHERE m.business_id=_biz AND public.money_balance(m.id,current_date)<>coalesce((SELECT sum(l.debit-l.credit) FROM journal_lines l WHERE l.business_id=_biz AND l.account_id=m.ledger_account_id),0)
 UNION ALL SELECT 'duplicate_invoices',count(*) FROM (SELECT invoice_no FROM sales WHERE business_id=_biz GROUP BY invoice_no HAVING count(*)>1 UNION ALL SELECT invoice_no FROM purchases WHERE business_id=_biz GROUP BY invoice_no HAVING count(*)>1)x
 UNION ALL SELECT 'return_quantities',count(*) FROM sale_items si WHERE si.business_id=_biz AND coalesce((SELECT sum(qty) FROM sales_return_items WHERE business_id=_biz AND sale_item_id=si.id),0)>si.qty
 UNION ALL SELECT 'payment_links',count(*) FROM customer_payments p WHERE p.business_id=_biz AND NOT EXISTS(SELECT 1 FROM money_transactions m WHERE m.id=p.money_txn_id AND m.business_id=_biz AND m.amount=p.amount)
 UNION ALL SELECT 'supplier_payment_links',count(*) FROM supplier_payments p WHERE p.business_id=_biz AND NOT EXISTS(SELECT 1 FROM money_transactions m WHERE m.id=p.money_txn_id AND m.business_id=_biz AND m.amount=p.amount)
 )q;
 RETURN jsonb_build_object('checked_at',now(),'business_date',(now() AT TIME ZONE 'Asia/Dhaka')::date,'checks',checks,
 'company',(SELECT jsonb_build_object('name',name,'type',type,'phone',phone,'address',address,'trade_license',trade_license,'currency',currency,'profile',guardian_profile) FROM businesses WHERE id=_biz),
 'metrics',jsonb_build_object('net_sales',coalesce((SELECT sum(subtotal-discount) FROM sales WHERE business_id=_biz AND status='posted'),0)-coalesce((SELECT sum(gross-discount_share) FROM sales_returns WHERE business_id=_biz),0),'today_sales',coalesce((SELECT sum(subtotal-discount) FROM sales WHERE business_id=_biz AND status='posted' AND sale_date=(now() AT TIME ZONE 'Asia/Dhaka')::date),0)-coalesce((SELECT sum(gross-discount_share) FROM sales_returns WHERE business_id=_biz AND return_date=(now() AT TIME ZONE 'Asia/Dhaka')::date),0),'gross_profit',coalesce((SELECT sum(subtotal-discount-cogs) FROM sales WHERE business_id=_biz AND status='posted'),0)-coalesce((SELECT sum(gross-discount_share-cost_total) FROM sales_returns WHERE business_id=_biz),0),'expenses',coalesce((SELECT sum(amount) FROM expenses WHERE business_id=_biz AND reversed_at IS NULL),0),'customer_due',coalesce((SELECT sum(current_due) FROM customer_balances WHERE business_id=_biz),0),'supplier_due',coalesce((SELECT sum(current_payable) FROM supplier_balances WHERE business_id=_biz),0),'cash_bank',coalesce((SELECT sum(balance) FROM money_account_balances WHERE business_id=_biz),0),'stock_value',coalesce((SELECT sum(qty*avg_cost) FROM stock WHERE business_id=_biz),0),'stock_units',coalesce((SELECT sum(qty) FROM stock WHERE business_id=_biz),0)),
 'alerts',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY last_seen DESC) FROM guardian_alerts a WHERE business_id=_biz),'[]'::jsonb),
 'loss_sales',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT s.id,s.invoice_no,s.sale_date,p.model,i.imei1,si.price,si.unit_cost,round(si.line_total*(1-s.discount/nullif(s.subtotal,0)),2) net_revenue,round(si.line_total*(1-s.discount/nullif(s.subtotal,0))-si.qty*si.unit_cost,2) margin,s.discount,s.paid,s.due FROM sales s JOIN sale_items si ON si.sale_id=s.id JOIN product_variants v ON v.id=si.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN product_imeis i ON i.id=si.imei_id WHERE s.business_id=_biz AND s.status='posted' AND si.line_total*(1-s.discount/nullif(s.subtotal,0))<si.qty*si.unit_cost AND si.qty>coalesce((SELECT sum(qty) FROM sales_return_items WHERE sale_item_id=si.id AND business_id=_biz),0))x),'[]'::jsonb),
 'restock',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT v.id,v.sku,p.model,v.storage,v.reorder_level,coalesce(sum(st.qty),0) available,greatest(v.reorder_level-coalesce(sum(st.qty),0),0) suggested_minimum FROM product_variants v JOIN products p ON p.id=v.product_id LEFT JOIN stock st ON st.variant_id=v.id AND st.business_id=_biz WHERE v.business_id=_biz AND v.status='active' AND v.reorder_level>0 GROUP BY v.id,p.model HAVING coalesce(sum(st.qty),0)<=v.reorder_level)x),'[]'::jsonb));
END $$;
REVOKE ALL ON FUNCTION public.guardian_snapshot(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.guardian_snapshot(uuid) TO authenticated;
CREATE TRIGGER audit_guardian_alerts AFTER INSERT OR UPDATE OR DELETE ON public.guardian_alerts FOR EACH ROW EXECUTE FUNCTION public.audit_row();
DO $$ DECLARE d text; BEGIN
 SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='_guardian_run';
 d:=replace(d,'si.price < si.unit_cost','si.price * (1-s.discount/nullif(s.subtotal,0)) < si.unit_cost AND si.qty>coalesce((SELECT sum(qty) FROM sales_return_items WHERE sale_item_id=si.id AND business_id=_biz),0)');
 d:=replace(d,' AND s.sale_date > current_date-90','');
 d:=replace(d,'WHERE x.category_id=e.category_id','WHERE x.business_id=_biz AND x.category_id=e.category_id');
 d:=replace(d,'LEFT JOIN stock st ON st.variant_id=v.id','LEFT JOIN stock st ON st.variant_id=v.id AND st.business_id=_biz');
 d:=replace(d,'  INSERT INTO guardian_alerts(business_id,check_code,severity,title,detail,ref_type,ref_id,fingerprint,last_seen)', E'  INSERT INTO _g SELECT ''consistency_''||(c->>''code''),''high'',''Data consistency: ''||(c->>''code''),(c->>''issues'')||'' discrepancy(s); owner review required'',''journal'',NULL,''consistency:''||(c->>''code'') FROM jsonb_array_elements(public.guardian_snapshot(_biz)->''checks'') c WHERE (c->>''issues'')::int>0;\n  INSERT INTO guardian_alerts(business_id,check_code,severity,title,detail,ref_type,ref_id,fingerprint,last_seen)');
 EXECUTE d;
END $$;